      return expression.value;
    } else {
      throw new Error(`Expected boolean isTemplate, received ${typeof expression.value}`);
    }
  } else {
    throw new Error(`Expected expression isTemplate, received ${isTemplate.type}`);
  }
};

interface MetaResult {
  title: string | undefined;
  of: string | undefined;
  name: string | undefined;
  summary: string | undefined;
  isTemplate: boolean;
  metaTags: string[] | undefined;
}

const extractTitle = (root: AnyNode, varToImport: Record<string, string>): MetaResult => {
  const result: MetaResult = {
    title: undefined,
    of: undefined,
    name: undefined,
    summary: undefined,
    isTemplate: false,
    metaTags: undefined,
  };

  const body = getProgramBody(root);
  const fragments = body.filter(
    (child: AnyNode) =>
      child.type === 'ExpressionStatement' && child.expression?.type === 'JSXFragment'
  );

  if (fragments.length > 1) throw new Error('duplicate contents');
  if (fragments.length === 0) return result;

  const fragment = fragments[0].expression;
  fragment.children.forEach((child: AnyNode) => {
    if (child.type === 'JSXElement') {
      const { openingElement } = child;
      const name = openingElement.name.name;
      if (name === 'Meta') {
        if (result.title || result.name || result.of) {
          throw new Error('Meta can only be declared once');
        }
        result.title = getAttrLiteral(openingElement, 'title');
        result.name = getAttrLiteral(openingElement, 'name');
        result.summary = getAttrLiteral(openingElement, 'summary');
        result.of = getOf(openingElement, varToImport);
        result.isTemplate = getIsTemplate(openingElement);
        result.metaTags = getTags(openingElement);
      }
    } else if (child.type === 'JSXExpressionContainer') {
      // Skip string literals & other JSX expressions (e.g. `{/* comments */}`)
    } else {
      throw new Error(`Unexpected JSX child: ${child.type}`);
    }
  });

  return result;
};

/**
 * Build a map from each imported identifier (or namespace alias) to the source module it was
 * imported from. Handles named imports, default imports and namespace (`* as X`) imports, and
 * processes every import declaration in the program regardless of how many statements they span.
 *
 * Accepts a Babel-ESTree-compatible `Program` node (ESTree `Program` or Babel `File`).
 */
export const extractImports = (root: AnyNode): Record<string, string> => {
  const varToImport: Record<string, string> = {};
  getProgramBody(root).forEach((child: AnyNode) => {
    if (child.type === 'ImportDeclaration') {
      const { source, specifiers } = child;
      if (isStringLiteral(source)) {
        specifiers.forEach((s: AnyNode) => {
          varToImport[s.local.name] = source.value.toString();
        });
      } else {
        throw new Error('MDX: unexpected import source');
      }
    }
  });
  return varToImport;
};

export const plugin = (store: any) => (root: any) => {
  const estree = toEstree(root);
  const varToImport = extractImports(estree);
  const { title, of, name, summary, isTemplate, metaTags } = extractTitle(estree, varToImport);
  store.title = title;
  store.of = of;
  store.name = name;
  store.summary = summary;
  store.isTemplate = isTemplate;
  store.metaTags = metaTags;
  store.imports = Array.from(new Set(Object.values(varToImport)));

  return root;
};

